  // Simulating a silver tier customer (2.5% discount)
  const line = { qty: 10, unitPrice: 1000, discountPercent: 2.5, vatRate: 0 };
  const total = lineTotal(line);
  assert.equal(total, 10000);
  const discount = lineDiscount(line);
  // Tier discount: 10000 * 2.5 / 100 = 250
  // After tier discount: 10000 - 250 = 9750
  // Bulk discount: 9750 * 2.5 / 100 = 243.75 rounded to 244
  // Total discount: 250 + 244 = 494
  assert.equal(discount, 494);
});

test('bulk discount with VAT calculated on amount after both discounts', () => {
  const line = { qty: 100, unitPrice: 1000, discountPercent: 0, vatRate: 21 };
  const total = lineTotal(line);
  assert.equal(total, 100000);
  const discount = lineDiscount(line);
  assert.equal(discount, 2500);
  const vat = lineVAT(line);
  // Taxable amount: 100000 - 2500 = 97500
  // VAT: 97500 * 21 / 100 = 20475
  assert.equal(vat, 20475);
});

test('invoiceTotals with bulk discount no regular discount', () => {
  const invoice = {
    lines: [{ qty: 10, unitPrice: 1000, discountPercent: 0, vatRate: 0 }],
  };
  const totals = invoiceTotals(invoice);
  assert.equal(totals.subtotal, 10000);
  assert.equal(totals.discount, 250);
  assert.equal(totals.vat, 0);
  assert.equal(totals.total, 9750);
});

test('invoiceTotals with bulk discount and regular discount', () => {
  const invoice = {
    lines: [{ qty: 100, unitPrice: 1000, discountPercent: 10, vatRate: 0 }],
  };
  const totals = invoiceTotals(invoice);
  assert.equal(totals.subtotal, 100000);
  // Regular discount: 100000 * 10 / 100 = 10000
  // After regular: 90000
  // Bulk: 90000 * 2.5 / 100 = 2250
  // Total discount: 12250
  assert.equal(totals.discount, 12250);
  assert.equal(totals.vat, 0);
  assert.equal(totals.total, 87750);
});

test('invoiceTotals with bulk discount and VAT', () => {
  const invoice = {
    lines: [{ qty: 50, unitPrice: 2000, discountPercent: 0, vatRate: 21 }],
  };
  const totals = invoiceTotals(invoice);
  assert.equal(totals.subtotal, 100000);
  // Bulk discount: 100000 * 2.5 / 100 = 2500
  assert.equal(totals.discount, 2500);
  // VAT on: 100000 - 2500 = 97500
  // VAT: 97500 * 21 / 100 = 20475
  assert.equal(totals.vat, 20475);
  assert.equal(totals.total, 115475);
});

test('invoiceTotals mixed lines with and without bulk discount', () => {
  const invoice = {
    lines: [
      { qty: 5, unitPrice: 1000, discountPercent: 0, vatRate: 0 },
      { qty: 15, unitPrice: 1000, discountPercent: 0, vatRate: 0 },
    ],
  };
  const totals = invoiceTotals(invoice);
  // Line 1: 5000, no bulk discount, discount = 0
  // Line 2: 15000, bulk discount = 375, discount = 375
  // Subtotal: 20000
  // Total discount: 375
  assert.equal(totals.subtotal, 20000);
  assert.equal(totals.discount, 375);
  assert.equal(totals.total, 19625);
});

test('bulk discount with multiple discounts and VAT', () => {
  const invoice = {
    lines: [
      { qty: 20, unitPrice: 1000, discountPercent: 10, vatRate: 21 },
      { qty: 5, unitPrice: 1000, discountPercent: 5, vatRate: 21 },
    ],
  };
  const totals = invoiceTotals(invoice);
  // Line 1: 20000
  //   Regular: 20000 * 10 / 100 = 2000
  //   After regular: 18000
  //   Bulk: 18000 * 2.5 / 100 = 450
  //   Total discount line 1: 2450
  //   Taxable: 17550
  //   VAT: 17550 * 21 / 100 = 3685.5 = 3686
  // Line 2: 5000
  //   Regular: 5000 * 5 / 100 = 250
  //   No bulk (qty < 10)
  //   Taxable: 4750
  //   VAT: 4750 * 21 / 100 = 997.5 = 998
  // Subtotal: 25000
  // Total discount: 2450 + 250 = 2700
  // Total VAT: 3686 + 998 = 4684
  assert.equal(totals.subtotal, 25000);
  assert.equal(totals.discount, 2700);
  assert.equal(totals.vat, 4684);
  assert.equal(totals.total, 26984);
});

test('bulk discount edge case at exactly 10 units', () => {
  const line10 = { qty: 10, unitPrice: 100, discountPercent: 0, vatRate: 0 };
  const line9 = { qty: 9, unitPrice: 100, discountPercent: 0, vatRate: 0 };

  const discount10 = lineDiscount(line10);
  const discount9 = lineDiscount(line9);

  assert.equal(discount9, 0);
  assert.equal(discount10, 25);
});

test('bulk discount with high regular discount', () => {
  const line = { qty: 100, unitPrice: 1000, discountPercent: 90, vatRate: 0 };
  // Regular: 100000 * 90 / 100 = 90000
  // After regular: 10000
  // Bulk: 10000 * 2.5 / 100 = 250
  // Total: 90250
  const discount = lineDiscount(line);
  assert.equal(discount, 90250);
});

test('bulk discount does not apply to qty < 10', () => {
  for (let qty = 0; qty < 10; qty++) {
    const line = { qty, unitPrice: 1000, discountPercent: 0, vatRate: 0 };
    const discount = lineDiscount(line);
    assert.equal(discount, 0, `qty ${qty} should have 0 discount`);
  }
});

test('bulk discount applies starting from qty = 10', () => {
  for (let qty = 10; qty <= 20; qty++) {
    const line = { qty, unitPrice: 1000, discountPercent: 0, vatRate: 0 };
    const discount = lineDiscount(line);
    const expectedBulk = roundCents((qty * 1000 * 2.5) / 100);
    assert.equal(discount, expectedBulk, `qty ${qty} should have bulk discount`);
  }
});

test('invoiceTotals preserves immutability with bulk discount', () => {
  const invoice = {
    lines: [{ qty: 10, unitPrice: 1000, discountPercent: 5, vatRate: 21 }],
  };
  const originalQty = invoice.lines[0].qty;
  const originalDiscount = invoice.lines[0].discountPercent;

  invoiceTotals(invoice);

  assert.equal(invoice.lines[0].qty, originalQty);
  assert.equal(invoice.lines[0].discountPercent, originalDiscount);
});

