test('bulk discount applies to qty >= 10', () => {
  const line9 = { qty: 9, unitPrice: 1000, discountPercent: 0, vatRate: 0 };
  const line10 = { qty: 10, unitPrice: 1000, discountPercent: 0, vatRate: 0 };
