test('bulk discount is 2.5% of amount after regular discount', () => {
  const line = { qty: 100, unitPrice: 1000, discountPercent: 20, vatRate: 0 };
  const total = lineTotal(line);
  assert.equal(total, 100000);
  const discount = lineDiscount(line);
  // Regular discount: 100000 * 20 / 100 = 20000
  // After regular discount: 100000 - 20000 = 80000
  // Bulk discount: 80000 * 2.5 / 100 = 2000
  // Total discount: 20000 + 2000 = 22000
  assert.equal(discount, 22000);
});

test('bulk discount applied after tier discount', () => {
  // Simulating a silver tier customer (2.5% discount)
