test('invoiceTotals correctly sums tier discounts', () => {
  const r = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [
      { sku: 'DES-HOUR', qty: 10 },
      { sku: 'ICON-SET', qty: 20 },
    ],
  });
  const totals = invoiceTotals(r.value);
  const expectedSubtotal = 10 * 8500 + 20 * 980;
  const expectedDiscount = Math.round((10 * 8500 * 5) / 100) + Math.round((20 * 980 * 5) / 100);
  const line1Total = 10 * 8500 - Math.round((10 * 8500 * 5) / 100);
  const line2Total = 20 * 980 - Math.round((20 * 980 * 5) / 100);
  const expectedVAT = Math.round((line1Total * 21) / 100) + Math.round((line2Total * 21) / 100);
  assert.equal(totals.subtotal, expectedSubtotal);
  assert.equal(totals.discount, expectedDiscount);
  assert.equal(totals.vat, expectedVAT);
  assert.equal(totals.total, expectedSubtotal - expectedDiscount + expectedVAT);
});

