1	import { ok, fail } from './result.js';
2	import { roundCents } from './money.js';
3	import { getCustomer, TIER_DISCOUNTS, normalizeId } from './customers.js';
4	import { getProduct } from './catalogue.js';
5	import { nextInvoiceNumber } from './numbering.js';
6	import { isValidDate, addDays } from './dates.js';
7	import { lineTotal, lineDiscount, lineVAT, invoiceTotals } from './totals.js';
8	
9	export { lineTotal, lineDiscount, lineVAT, invoiceTotals };
10	
11	/**
12	 * Validate discount percent value.
13	 * @param {any} discountPercent
14	 * @returns {boolean}
15	 */
16	function isValidDiscount(discountPercent) {
17	  return discountPercent != null && typeof discountPercent === 'number' && discountPercent >= 0 && discountPercent <= 100;
18	}
19	
20	/**
21	 * Calculate due date based on payment terms.
22	 * @param {string} issueDate - YYYY-MM-DD format
23	 * @param {string} terms - 'NET14', 'NET30', or 'EOM'
24	 * @returns {string} due date in YYYY-MM-DD format
25	 */
26	function calculateDueDate(issueDate, terms) {
27	  if (terms === 'NET14') {
28	    return addDays(issueDate, 14);
29	  } else if (terms === 'NET30') {
30	    return addDays(issueDate, 30);
31	  } else if (terms === 'EOM') {
32	    // Get the last day of the month of issueDate
33	    const [year, month] = issueDate.split('-');
34	    const nextMonth = parseInt(month) + 1;
35	    const yearForNextMonth = nextMonth === 13 ? parseInt(year) + 1 : year;
36	    const monthForNextMonth = nextMonth === 13 ? '01' : String(nextMonth).padStart(2, '0');
37	    const firstOfNextMonth = `${yearForNextMonth}-${monthForNextMonth}-01`;
38	    // Last day of current month is one day before first of next month
39	    return addDays(firstOfNextMonth, -1);
40	  }
41	}
42	
43	/**
44	 * Validate payment terms.
45	 * @param {any} terms
46	 * @returns {boolean}
47	 */
48	function isValidTerms(terms) {
49	  return terms === 'NET14' || terms === 'NET30' || terms === 'EOM';
50	}
51	
52	/**
53	 * Create a new invoice.
54	 * @param {{ customerId: string, issueDate: string, lines: Array<{ sku: string, qty: number, discountPercent?: number }>, terms?: string }} input
55	 * @returns {{ ok: true, value: { customerId: string, issueDate: string, status: string, lines: Array, terms: string, dueDate: string } } | { ok: false, error: string }}
56	 */
57	export function createInvoice({ customerId, issueDate, lines, terms = 'NET30' }) {
58	  // Normalize and validate customer
59	  const normalizedCustomerId = normalizeId(customerId);
60	  const customerResult = getCustomer(normalizedCustomerId);
61	  if (!customerResult.ok) return customerResult;
62	
63	  // Validate date
64	  if (!isValidDate(issueDate)) {
65	    return fail('DATE_INVALID');
66	  }
67	
68	  // Validate terms
69	  if (!isValidTerms(terms)) {
70	    return fail('TERMS_INVALID');
71	  }
72	
73	  // Validate lines array is not empty
74	  if (!Array.isArray(lines) || lines.length === 0) {
75	    return fail('NO_LINES');
76	  }
77	
78	  // Validate and build each line
79	  const invoiceLines = [];
80	  const customer = customerResult.value;
81	  for (const line of lines) {
82	    // Validate quantity
83	    if (!Number.isInteger(line.qty) || line.qty <= 0) {
84	      return fail('QTY_INVALID');
85	    }
86	
87	    // Determine discount percent: explicit value always wins, otherwise use tier discount
88	    let discountPercent;
89	    if (Object.prototype.hasOwnProperty.call(line, 'discountPercent')) {
90	      // Line has explicit discountPercent
91	      if (!isValidDiscount(line.discountPercent)) {
92	        return fail('DISCOUNT_INVALID');
93	      }
94	      discountPercent = line.discountPercent;
95	    } else {
96	      // Use tier discount
97	      discountPercent = TIER_DISCOUNTS[customer.tier] ?? 0;
98	    }
99	
100	    // Validate SKU exists and get product details
101	    const productResult = getProduct(line.sku);
102	    if (!productResult.ok) return productResult;
103	
104	    const product = productResult.value;
105	    invoiceLines.push({
106	      sku: line.sku,
107	      name: product.name,
108	      qty: line.qty,
109	      unitPrice: product.unitPrice,
110	      vatRate: product.vatRate,
111	      discountPercent,
112	    });
113	  }
114	
115	  const dueDate = calculateDueDate(issueDate, terms);
116	
117	  return ok({
118	    customerId: normalizedCustomerId,
119	    issueDate,
120	    status: 'draft',
121	    lines: invoiceLines,
122	    terms,
123	    dueDate,
124	  });
125	}
126	
127	
128	/**
129	 * Add or update a line on an invoice.
130	 * @param {{ status: string, lines: Array<{ sku: string, name: string, qty: number, unitPrice: number, vatRate: number, discountPercent?: number }> }} invoice
131	 * @param {{ sku: string, qty: number, discountPercent?: number }} input
132	 * @returns {{ ok: true, value: object } | { ok: false, error: string }}
133	 */
134	export function addLine(invoice, { sku, qty, discountPercent }) {
135	  // Validate invoice is draft
136	  if (invoice.status !== 'draft') {
137	    return fail('NOT_DRAFT');
138	  }
139	
140	  // Validate quantity
141	  if (!Number.isInteger(qty) || qty <= 0) {
142	    return fail('QTY_INVALID');
143	  }
144	
145	  // Determine discount percent: explicit value always wins, otherwise use tier discount
146	  let discount;
147	  if (Object.prototype.hasOwnProperty.call(arguments[1], 'discountPercent')) {
148	    // Explicit discountPercent provided
149	    if (!isValidDiscount(discountPercent)) {
150	      return fail('DISCOUNT_INVALID');
151	    }
152	    discount = discountPercent;
153	  } else {
154	    // Use tier discount (customerId is already normalized in invoice)
155	    const customerResult = getCustomer(invoice.customerId);
156	    if (!customerResult.ok) return customerResult;
157	    const customer = customerResult.value;
158	    discount = TIER_DISCOUNTS[customer.tier] ?? 0;
159	  }
160	
161	  // Validate SKU exists and get product details
162	  const productResult = getProduct(sku);
163	  if (!productResult.ok) return productResult;
164	
165	  const product = productResult.value;
166	  const newLines = invoice.lines.map((line) => ({ ...line }));
167	
168	  // Find existing line with this SKU
169	  const existingLineIndex = newLines.findIndex((line) => line.sku === sku);
170	
171	  if (existingLineIndex >= 0) {
172	    // Update existing line
173	    newLines[existingLineIndex].qty += qty;
174	    if (Object.prototype.hasOwnProperty.call(arguments[1], 'discountPercent')) {
175	      newLines[existingLineIndex].discountPercent = discountPercent;
176	    }
177	  } else {
178	    // Add new line
179	    newLines.push({
180	      sku,
181	      name: product.name,
182	      qty,
183	      unitPrice: product.unitPrice,
184	      vatRate: product.vatRate,
185	      discountPercent: discount,
186	    });
187	  }
188	
189	  return ok({
190	    ...invoice,
191	    lines: newLines,
192	  });
193	}
