201	export function removeLine(invoice, sku) {
202	  // Validate invoice is draft
203	  if (invoice.status !== 'draft') {
204	    return fail('NOT_DRAFT');
205	  }
206	
207	  // Find the line to remove
208	  const lineIndex = invoice.lines.findIndex((line) => line.sku === sku);
209	  if (lineIndex === -1) {
210	    return fail('LINE_NOT_FOUND');
211	  }
212	
213	  // Check if removing would leave no lines
214	  if (invoice.lines.length === 1) {
215	    return fail('NO_LINES');
216	  }
217	
218	  const newLines = invoice.lines
219	    .slice(0, lineIndex)
220	    .concat(invoice.lines.slice(lineIndex + 1))
221	    .map((line) => ({ ...line }));
222	
223	  return ok({
224	    ...invoice,
225	    lines: newLines,
226	  });
227	}
