252	 * @param {{ status: string, voucher?: { code: string, amount: number } }} invoice
253	 * @param {{ code: string, amount: number }} voucher
254	 * @returns {{ ok: true, value: object } | { ok: false, error: string }}
255	 */
256	export function applyVoucher(invoice, { code, amount }) {
257	  // Validate invoice is draft
258	  if (invoice.status !== 'draft') {
259	    return fail('NOT_DRAFT');
260	  }
261	
262	  // Validate amount is a positive integer
263	  if (!Number.isInteger(amount) || amount <= 0) {
