12	/**
13	 * Calculate the discount amount for a single line item.
14	 * Includes both regular discount and bulk discount (2.5% extra for qty >= 10).
15	 * Bulk discount is applied after regular discount.
16	 * @param {{ qty: number, unitPrice: number, discountPercent?: number }} line
17	 * @returns {number} total discount in cents, clamped at 0
18	 */
19	export function lineDiscount(line) {
20	  const discountPercent = line.discountPercent ?? 0;
21	  const total = lineTotal(line);
22	  const regularDiscount = roundCents((total * discountPercent) / 100);
23	
24	  // Bulk discount: extra 2.5% off on qty >= 10, applied after regular discount
25	  let bulkDiscount = 0;
26	  if (line.qty >= 10) {
27	    const afterRegularDiscount = Math.max(0, total - regularDiscount);
28	    bulkDiscount = roundCents((afterRegularDiscount * 2.5) / 100);
29	  }
30	
31	  const totalDiscount = Math.max(0, regularDiscount + bulkDiscount);
32	  return totalDiscount;
33	}
