35	/**
36	 * Calculate the VAT amount for a single line item.
37	 * @param {{ qty: number, unitPrice: number, discountPercent?: number, vatRate: number }} line
38	 * @returns {number} VAT in cents, clamped at 0
39	 */
40	export function lineVAT(line) {
41	  const total = lineTotal(line);
42	  const discount = lineDiscount(line);
43	  const taxableAmount = Math.max(0, total - discount);
44	  const vat = roundCents((taxableAmount * line.vatRate) / 100);
45	  return Math.max(0, vat);
46	}
