49	 * Calculate subtotal, discount, VAT, voucher, and total for an invoice.
50	 * @param {{ lines: Array<{ qty: number, unitPrice: number, discountPercent?: number, vatRate: number }>, voucher?: { code: string, amount: number } }} invoice
51	 * @returns {{ subtotal: number, discount: number, vat: number, voucher: number, total: number }} amounts in cents
52	 */
53	export function invoiceTotals(invoice) {
54	  const subtotal = roundCents(invoice.lines.reduce((sum, line) => sum + lineTotal(line), 0));
55	  const discount = roundCents(invoice.lines.reduce((sum, line) => sum + lineDiscount(line), 0));
56	  const vat = roundCents(invoice.lines.reduce((sum, line) => sum + lineVAT(line), 0));
57	  const voucher = invoice.voucher ? invoice.voucher.amount : 0;
58	  const total = Math.max(0, roundCents(subtotal - discount + vat - voucher));
59	  return {
60	    subtotal,
61	    discount,
62	    vat,
63	    voucher,
64	    total,
65	  };
66	}
