test('invoiceTotals with tier discount and VAT', () => {
  const invoice = {
    lines: [{ qty: 100, unitPrice: 1000, discountPercent: 5, vatRate: 21 }],
  };
  const totals = invoiceTotals(invoice);
  assert.equal(totals.subtotal, 100000);
  // Regular: 5000, after 95000, bulk 2375, total 7375
  assert.equal(totals.discount, 7375);
  // VAT on: 100000 - 7375 = 92625
  // VAT: 92625 * 21 / 100 = 19451.25 = 19451
  assert.equal(totals.vat, 19451);
  assert.equal(totals.total, 112076);
});

test('invoiceTotals with explicit discount and VAT', () => {
  const invoice = {
    lines: [{ qty: 100, unitPrice: 1000, discountPercent: 0, vatRate: 21 }],
  };
  const totals = invoiceTotals(invoice);
  assert.equal(totals.subtotal, 100000);
  // qty >= 10 gets bulk discount: 100000 * 2.5 / 100 = 2500
  assert.equal(totals.discount, 2500);
  // VAT on: 100000 - 2500 = 97500
  // VAT: 97500 * 21 / 100 = 20475
  assert.equal(totals.vat, 20475);
  assert.equal(totals.total, 117975);
});

test('bulk discount applies to qty >= 10', () => {
  const line9 = { qty: 9, unitPrice: 1000, discountPercent: 0, vatRate: 0 };
