1	import { ok, fail } from './result.js';
2	
3	/**
4	 * Exchange rates: units of that currency per euro.
5	 * EUR: 1 (base), USD: 1.085, GBP: 0.8425
6	 */
7	export const RATES = { EUR: 1, USD: 1.085, GBP: 0.8425 };
8	
9	/**
10	 * Round a (possibly fractional) number of cents to a whole cent, half to even (banker's rounding):
11	 * 124.5 -> 124, 125.5 -> 126, 2.4 -> 2, -0.5 -> 0.
12	 * @param {number} x
13	 * @returns {number}
14	 */
15	export function roundCents(x) {
16	  const r = Math.round(x * 1e6) / 1e6; // drop binary noise such as 124.49999999999999
17	  const floor = Math.floor(r);
18	  const diff = r - floor;
19	  if (diff > 0.5) return floor + 1;
20	  if (diff < 0.5) return floor === 0 ? 0 : floor;
21	  return floor % 2 === 0 ? floor : floor + 1;
22	}
23	
24	/**
25	 * Format cents as euros for people: 123456 -> "€1,234.56", -5 -> "-€0.05".
26	 * @param {number} cents
27	 * @returns {string}
28	 */
29	export function formatEuros(cents) {
30	  const sign = cents < 0 ? '-' : '';
31	  const abs = Math.abs(cents);
32	  const euros = Math.floor(abs / 100).toString().replace(/\B(?=(\d{3})+(?!\d))/g, ',');
33	  return `${sign}€${euros}.${String(abs % 100).padStart(2, '0')}`;
34	}
35	
36	/**
37	 * Parse a euro amount typed by a person ("12", "12.5", "1,234.56") into cents.
38	 * @param {string} text
39	 * @returns {{ ok: true, value: number } | { ok: false, error: string }}
40	 */
41	export function parseEuros(text) {
42	  const m = /^(\d{1,3}(?:,\d{3})*|\d+)(?:\.(\d{1,2}))?$/.exec(String(text).trim());
43	  if (!m) return fail('AMOUNT_INVALID');
44	  const euros = Number(m[1].replace(/,/g, ''));
45	  const cents = Number((m[2] ?? '').padEnd(2, '0'));
46	  return ok(euros * 100 + cents);
47	}
48	
49	/**
50	 * Convert euros (in cents) to another currency.
51	 * @param {number} cents - amount in euros (cents)
52	 * @param {string} currency - currency code ('EUR', 'USD', 'GBP')
53	 * @returns {{ ok: true, value: number } | { ok: false, error: string }} amount in that currency's cents
54	 */
55	export function convert(cents, currency) {
56	  if (!(currency in RATES)) {
57	    return fail('UNKNOWN_CURRENCY');
58	  }
59	  const rate = RATES[currency];
60	  const convertedCents = roundCents(cents * rate);
61	  return ok(convertedCents);
62	}
63	
64	/**
65	 * Format cents in a specified currency: 123456 -> "$1,234.56" (USD), "£1,234.56" (GBP), etc.
66	 * @param {number} cents
67	 * @param {string} currency - currency code ('EUR', 'USD', 'GBP')
68	 * @returns {string}
69	 */
70	export function formatMoney(cents, currency) {
71	  const symbols = { EUR: '€', USD: '$', GBP: '£' };
72	  const symbol = symbols[currency] || '';
73	
74	  const sign = cents < 0 ? '-' : '';
75	  const abs = Math.abs(cents);
76	  const majorUnits = Math.floor(abs / 100).toString().replace(/\B(?=(\d{3})+(?!\d))/g, ',');
77	  return `${sign}${symbol}${majorUnits}.${String(abs % 100).padStart(2, '0')}`;
78	}
