11	/**
12	 * Validate discount percent value.
13	 * @param {any} discountPercent
14	 * @returns {boolean}
15	 */
16	function isValidDiscount(discountPercent) {
17	  return discountPercent != null && typeof discountPercent === 'number' && discountPercent >= 0 && discountPercent <= 100;
18	}
19	
20	/**
21	 * Calculate due date based on payment terms.
22	 * @param {string} issueDate - YYYY-MM-DD format
23	 * @param {string} terms - 'NET14', 'NET30', or 'EOM'
24	 * @returns {string} due date in YYYY-MM-DD format
25	 */
26	function calculateDueDate(issueDate, terms) {
27	  if (terms === 'NET14') {
28	    return addDays(issueDate, 14);
29	  } else if (terms === 'NET30') {
30	    return addDays(issueDate, 30);
31	  } else if (terms === 'EOM') {
32	    // Get the last day of the month of issueDate
33	    const [year, month] = issueDate.split('-');
34	    const nextMonth = parseInt(month) + 1;
35	    const yearForNextMonth = nextMonth === 13 ? parseInt(year) + 1 : year;
36	    const monthForNextMonth = nextMonth === 13 ? '01' : String(nextMonth).padStart(2, '0');
37	    const firstOfNextMonth = `${yearForNextMonth}-${monthForNextMonth}-01`;
38	    // Last day of current month is one day before first of next month
39	    return addDays(firstOfNextMonth, -1);
40	  }
41	}
42	
43	/**
44	 * Validate payment terms.
45	 * @param {any} terms
46	 * @returns {boolean}
